#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;
    int a = -1e9, b = -1e9;
    for (int i = 0; i < N; ++i) {
        int x;
        cin >> x;
        a = max(a, x);
    }
    for (int i = 0; i < N; ++i) {
        int x;
        cin >> x;
        b = max(b, x);
    }
    cout << a + b << endl;
}
